const want = $('Config').first().json.locales;
const langs = ($input.first().json.languages || []);
const have = langs.filter(l => want.includes(l.lang_iso)).map(l => ({ iso: l.lang_iso, id: l.lang_id }));
const en = langs.find(l => l.lang_iso === 'en');
return [{ json: { have, ids: [en ? en.lang_id : 640, ...have.map(h => h.id)].join(','), project_langs: langs.map(l => l.lang_iso) } }];

const cfg = $('Config').first().json;
const meta = $('Pick Languages').first().json;
const keys = [];
for (const n of ['Keys p1', 'Keys p2']) { let b; try { b = $(n).first().json; } catch (e) { continue; } if (b && Array.isArray(b.keys)) keys.push(...b.keys); }
const norm = s => String(s || '').replace(/[\u00a0\s]+/g, ' ').replace(/[’‘]/g, "'").replace(/[“”]/g, '"').replace(/…/g, '...').trim();
const low = s => norm(s).toLowerCase();
const byEn = new Map(), byLow = new Map(); const enVals = [];
for (const k of keys) { if (k.is_archived) continue;
  const tr = {}; let enV = null;
  for (const t of (k.translations || [])) { let v = t.translation; if (k.is_plural) { try { const o = JSON.parse(v); v = o.other || Object.values(o)[0] || ''; } catch (e) {} }
    if (t.language_iso === 'en') enV = v; else if (v) tr[t.language_iso] = v; }
  if (!enV) continue; const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
  const rec = { key: name, plural: !!k.is_plural, t: tr };
  enVals.push(norm(enV)); if (!byEn.has(norm(enV))) byEn.set(norm(enV), rec); if (!byLow.has(low(enV))) byLow.set(low(enV), rec); }
const bigr = s => { s = low(s); const a = []; for (let i = 0; i < s.length - 1; i++) a.push(s.slice(i, i + 2)); return a; };
const dice = (a, b) => { const A = bigr(a), B = bigr(b); if (!A.length || !B.length) return 0; const m = new Map(); for (const x of A) m.set(x, (m.get(x) || 0) + 1); let hit = 0; for (const x of B) { const c = m.get(x); if (c) { hit++; m.set(x, c - 1); } } return 2 * hit / (A.length + B.length); };
const matches = {}, case_only = {}, missing = [], drift = {};
for (const s of cfg.strings) { const n = norm(s);
  if (byEn.has(n)) { matches[s] = byEn.get(n); continue; }
  if (byLow.has(low(s))) { matches[s] = byLow.get(low(s)); case_only[s] = byLow.get(low(s)).key; continue; }
  missing.push(s);
  let best = null, bs = 0; for (const v of enVals) { if (Math.abs(v.length - n.length) > Math.max(6, n.length * 0.3)) continue; const d = dice(n, v); if (d > bs) { bs = d; best = v; } }
  if (bs >= 0.85) drift[s] = { en: best, score: Math.round(bs * 100) / 100, key: byEn.get(best).key }; }
return [{ json: { project_langs: meta.project_langs, real_locales: meta.have.map(h => h.iso), keys_read: keys.length, en_values: enVals.length, matched: Object.keys(matches).length, matches, case_only, missing, drift } }];
